// ============================================================
// VALIDATION DU RAPPEL DE LOT — vocalisation
// ============================================================
// Appelé par `Claude - Batch Poller` (`POST Callback`) quand le lot Anthropic est
// terminé. Le poller retire `api_key` et `callback_url` avant d'envoyer.
const input = $input.first().json;
const body = input.body || input;

// ⚠️ `metadata` peut arriver en CHAÎNE JSON. C'est le cas défensif déjà rencontré
// sur le callback de traduction : le lot a traversé Redis, et selon le chemin la
// metadata en ressort sérialisée. Sans ce parse, `carte_items` est undefined et
// TOUS les résultats deviennent non rattachables — un lot entier payé puis jeté.
let md = body.metadata;
if (typeof md === 'string') {
  try { md = JSON.parse(md); } catch (e) { md = {}; }
}
md = md || {};

const resultats = Array.isArray(body.results) ? body.results : [];
const errors = [];
if (resultats.length === 0) {
  errors.push('Aucun resultat dans le rappel du lot');
}
// Sans la carte, un résultat n'est rattachable à rien : le texte est payé, produit,
// et impossible à écrire. On refuse bruyamment plutôt que d'écrire au hasard.
if (!md.carte_items || typeof md.carte_items !== 'object') {
  errors.push('metadata.carte_items absente — resultats non rattachables');
}

return [{
  json: {
    valid: errors.length === 0,
    errors: errors,
    data: {
      job_id: md.job_id || body.job_id || null,
      project_id: md.project_id || null,
      batch_id: body.batch_id || null,
      correlation_id: body.correlation_id || md.correlation_id || null,
      client_metadata: md.client_metadata || null,
      // ⚠️ Aucune valeur de repli inventée : `anthropic` est ici une CERTITUDE, pas
      // un défaut — le dispatcher refuse tout modèle non Claude, et les Message
      // Batches n'existent que chez Anthropic. Le modèle, lui, vient du lot.
      provider: md.provider || 'anthropic',
      model: md.model || null,
      traite: md.traite || null,
      page: md.page || null,
      carte_items: md.carte_items || {},
      results: resultats
    }
  }
}];

// ============================================================
// ÉCLATER LES RÉSULTATS — un item n8n par vocalisation
// ============================================================
const data = $input.first().json.data;
const carte = data.carte_items || {};
const resultats = data.results || [];

// ⚠️ LE PIÈGE MULTI-FOURNISSEURS, repris de `Recoller Vocalisation`. Chaque
// fournisseur nomme différemment une génération terminée, et le lot passe par
// Anthropic : `end_turn` / `stop_sequence` sont NORMAUX, `max_tokens` est une
// troncature. Tester `!== 'stop'` (la forme d'OpenAI) déclarerait tronquée
// CHAQUE réponse du lot, et la vocalisation échouerait systématiquement.
const FINS_NORMALES = ['end_turn', 'stop_sequence', 'stop'];

// ⚠️ UN `stop_reason` ABSENT N'EST PAS UNE TRONCATURE. Le poller ne remonte ce
// champ que depuis azy.daily#706 : si `Claude - Batch Poller` n'est pas encore
// réimporté, il vaut `undefined` sur tous les items. Refuser dans ce cas
// jetterait un lot entier déjà payé à cause d'un ordre de réimport. On ne refuse
// donc QUE sur une valeur PRÉSENTE et anormale.
const finAcceptable = (r) => r === undefined || r === null || r === ''
  || FINS_NORMALES.indexOf(String(r).toLowerCase()) !== -1;

// ⚠️ `vocalized_by` est ÉCRIT EN BASE côté torah.api. On garde EXACTEMENT la forme
// `llm:<modele>` du chemin synchrone, pour qu'aucun consommateur n'ait à
// distinguer une ligne venue du lot d'une ligne venue du direct. La provenance
// reste lisible dans le nom du modèle (`llm:claude-…` contre `llm:gpt-4o`).
const signature = 'llm:' + (data.model || 'claude');

const items = resultats.map((r, rang) => {
  const ref = String(r && r.custom_id);
  const cible = carte[ref] || {};
  const texte = (r && typeof r.text === 'string') ? r.text.trim() : '';

  let souci = null;
  if (!r || r.ok !== true) {
    souci = { code: 'BATCH_ITEM_FAILED',
              message: String((r && r.error && (r.error.message || r.error.code)) || 'echec du lot') };
  } else if (!carte[ref]) {
    // Résultat sans cible : payé, produit, non rattachable. À remonter, jamais à écrire.
    souci = { code: 'CIBLE_INTROUVABLE',
              message: 'custom_id ' + ref + ' absent de carte_items' };
  } else if (!texte) {
    souci = { code: 'EMPTY_LLM_RESPONSE', message: 'le modele a rendu une reponse vide' };
  } else if (!finAcceptable(r.stop_reason)) {
    // Un texte tronqué enregistré comme complet, ce sont des nekudot manquantes en
    // fin de texte, sans aucune erreur. Même doctrine que le chemin synchrone.
    souci = { code: 'GENERATION_TRONQUEE',
              message: 'generation interrompue (stop_reason=' + String(r.stop_reason)
                     + ') texte tronque, non enregistre' };
  }

  return { json: {
    rang: rang,
    custom_id: ref,
    job_id: data.job_id,
    project_id: data.project_id,
    correlation_id: data.correlation_id,
    client_metadata: data.client_metadata,
    provider: data.provider,
    model: data.model,
    traite: data.traite,
    page: data.page,
    ok: !souci,
    error: souci,
    original: cible.original || null,
    vocalized_text: souci ? null : texte,
    // Forme EXACTE attendue par /api/vocalization/save, reprise de
    // `Extract GPT Response` du chemin synchrone : les trois identifiants sont
    // présents, à null quand ils ne s'appliquent pas.
    _saveData: souci ? null : {
      segment_id: cible.segment_id || null,
      source_text_id: cible.source_text_id || null,
      commentary_id: cible.commentary_id || null,
      vocalized_text: texte,
      vocalized_by: signature
    }
  }};
});

// ⚠️ SENTINELLE. Si RIEN n'est enregistrable, il ne faut pas pour autant que la
// chaîne s'arrête : le job doit être clos et l'appelant prévenu. Un nœud HTTP sans
// item d'entrée ne s'exécute pas, et la branche entière resterait muette — le job
// resterait « processing » pour toujours.
const aEnvoyer = items.filter((it) => it.json._saveData);
if (aEnvoyer.length === 0) {
  return [{ json: { aucun_envoi: true, job_id: data.job_id, project_id: data.project_id,
                    correlation_id: data.correlation_id, client_metadata: data.client_metadata,
                    traite: data.traite, page: data.page, total: items.length,
                    soucis: items.map((it) => it.json.error).filter(Boolean) } }];
}
return items;

// ============================================================
// AGRÉGER — ce qui est réellement en base, et ce qui ne l'est pas
// ============================================================
// Deux entrées possibles : la sortie du nœud de sauvegarde (un item par appel),
// ou la sentinelle `aucun_envoi` quand il n'y avait rien à écrire.
const entrees = $input.all().map((x) => x.json);
const sentinelle = entrees.length === 1 && entrees[0] && entrees[0].aucun_envoi === true;

// Les items PRÉVUS, lus à la source : le nœud de sauvegarde ne rend que des
// réponses HTTP, et on a besoin de savoir à quoi chacune correspond. `Éclater
// Résultats` n'est pas dans une boucle, donc .all() rend bien ses N items.
const prevus = sentinelle ? [] : $('Éclater Résultats').all().map((x) => x.json);
const base = sentinelle ? entrees[0] : prevus[0] || {};

// ⚠️ `Sauvegarder Vocalisation` porte `continueRegularOutput` : une erreur HTTP
// n'arrête pas la chaîne, mais elle n'émet alors AUCUN statusCode — c'est le
// défaut d'azy.daily#442. D'où `fullResponse: true` sur le nœud, et une lecture
// qui traite l'absence de code comme un échec plutôt que comme un succès.
const reponses = sentinelle ? [] : entrees;
let enregistres = 0;
const echecs = [];

prevus.forEach((it, i) => {
  if (!it._saveData) {
    echecs.push({ custom_id: it.custom_id, error: it.error });
    return;
  }
  const rep = reponses[i];
  const codeHttp = rep && rep.statusCode;
  if (codeHttp >= 200 && codeHttp < 300) {
    enregistres += 1;
  } else {
    echecs.push({ custom_id: it.custom_id, error: { code: 'SAVE_FAILED',
      message: 'ecriture refusee par torah-api (HTTP ' + String(codeHttp || 'inconnu') + ')' } });
  }
});

if (sentinelle) {
  (base.soucis || []).forEach((s) => echecs.push({ custom_id: null, error: s }));
}

const total = sentinelle ? (base.total || 0) : prevus.length;
return [{ json: {
  success: enregistres > 0,
  job_id: base.job_id || null,
  project_id: base.project_id || null,
  correlation_id: base.correlation_id || null,
  client_metadata: base.client_metadata || null,
  traite: base.traite || null,
  page: base.page || null,
  resume: { total: total, enregistres: enregistres, echecs: echecs.length },
  echecs: echecs.slice(0, 20)
} }];

// ============================================================
// PRÉPARER L'ÉVÉNEMENT REDIS — fin de vocalisation
// ============================================================
// ⚠️ L'APPARIEMENT SE FAIT PAR `job_id` POUR LA VOCALISATION, pas par
// `correlation_id` (qui sert à l'export). Se tromper de clé publie un événement
// que personne ne sait rattacher.
//
// ⚠️ ET CET ÉVÉNEMENT N'A AUCUN CONSOMMATEUR À CE JOUR : le plugin est
// dispatch-only depuis #514/PR#275. Un XADD réussi prouve qu'on a PUBLIÉ, pas
// qu'on a été lu. L'appelant doit sonder /api/v2/jobs/{job_id} — c'est le seul
// canal qui fasse foi, et c'est pour ça que `Update Job` passe AVANT.
const r = $input.first().json;
const resume = r.resume || {};

// Pas de repli `|| ''` sur le job_id : il publierait du VIDE, qui ressemble à un
// événement valide et ne s'apparie à rien.
const champs = {
  event: 'vocalization_complete',
  job_id: String(r.job_id),
  mode: 'batch',
  success: String(!!r.success),
  total: String(resume.total || 0),
  enregistres: String(resume.enregistres || 0),
  echecs: String(resume.echecs || 0),
  traite: String(r.traite || ''),
  page: String(r.page || ''),
  completed_at: new Date().toISOString()
};
if (r.correlation_id) { champs.correlation_id = String(r.correlation_id); }

return [{ json: { stream: 'llm:results:stream', fields: champs, max_len: 10000 } }];

// Réponse au poller. Elle n'est lue par personne d'autre : le poller ne fait rien
// du corps, il journalise seulement le code. On la garde explicite pour les
// exécutions, qui sont la seule trace consultable après coup — et pour ~2,4 jours
// seulement, la rétention étant au COMPTE (~10 000) et non à la durée.
const r = $input.first().json;
return [{ json: {
  success: !!r.success,
  job_id: r.job_id || null,
  mode: 'batch',
  resume: r.resume || null,
  echecs: r.echecs || []
} }];

const v = $input.first().json;
return [{ json: {
  success: false,
  error: { code: 400, message: (v.errors || []).join(', '), status: 'BAD_REQUEST' }
} }];
